insert into chat_messages (id, thread_id, sender_id, body, created_at) values
('t1-m0', 't1', 'e4', 'Hey! Are you on the floor tomorrow morning?', '2026-07-06T19:56:14.356Z'),
('t1-m1', 't1', 'e1', 'Yep, opening at 6. Why’s up?', '2026-07-06T22:56:14.356Z'),
('t1-m2', 't1', 'e4', 'Could you save me a couple of the new pastries? 🥐', '2026-07-06T23:56:14.356Z'),
('t1-m3', 't1', 'e4', 'Also — is the espresso machine fixed?', '2026-07-07T00:56:14.356Z'),
('t2-m0', 't2', 'e2', 'Great work today everyone — record Saturday covers! 🎉', '2026-07-06T21:56:14.356Z'),
('t2-m1', 't2', 'e6', 'Team effort 💪', '2026-07-06T22:56:14.356Z'),
('t2-m2', 't2', 'e12', 'Kitchen held it down 🔥', '2026-07-06T22:56:14.356Z'),
('t2-m3', 't2', 'e1', 'Proud of this crew. Drinks on me next week.', '2026-07-06T23:56:14.356Z'),
('t3-m0', 't3', 'e13', 'We’re low on the truffle oil for the special.', '2026-07-06T20:56:14.356Z'),
