('t4-m1', 't4', 'e7', 'I’ve got it — see you at handover.', '2026-07-06T22:56:14.356Z')
insert into recognition (id, from_id, to_id, message, created_at, reactions) values
('r1', 'e2', 'e6', 'Emma jumped on three open shifts this week and saved our weekend. Absolute legend. 🙌', '2026-07-06T17:56:14.356Z', 14),
('r2', 'e1', 'e12', 'Marcus trained two new line cooks and kept the pass spotless during Saturday’s rush.', '2026-07-05T23:56:14.356Z', 9),
('r3', 'e19', 'e10', 'Zoe’s energy at the host stand is unmatched — guests keep asking for her by name.', '2026-07-04T23:56:14.356Z', 21)
